"""The country parts of the legal notice in Vietnamese (Vietnam's own, kept in ``jurisdictions``, is repeated here verbatim)."""

SECTIONS: dict[str, str] = {
    "JP": """Nhật Bản. Bản quyền: khoản 1 Điều 30 Luật Bản quyền cho phép bạn sao chép một tác phẩm để sử dụng cho cá nhân hoặc gia đình, và Điều 47-6 cho phép bạn dịch tác phẩm cho mục đích sử dụng đó; việc cho người khác xem hoặc chuyển cho người khác bản sao hay bản dịch là hành vi xâm phạm (Điều 49). Ngoại lệ này không áp dụng cho bản sao được tạo ra bằng cách vượt qua biện pháp bảo vệ (điểm (ii) khoản 1 Điều 30); TASlation chụp lại những gì trình xem đã hiển thị trên màn hình và không vượt qua bất cứ thứ gì; ảnh chụp chỉ được giữ trong bộ nhớ và nhiều nhất cũng chỉ là một bản sao phát sinh kèm theo quá trình xử lý trên máy tính, được Điều 47-4 cho phép. Điều khoản của cửa hàng sách điện tử của bạn vẫn có thể cấm việc này. Nội dung: tàng trữ hình ảnh tình dục của trẻ em có thật là tội phạm kể từ lần sửa đổi năm 2014 của Luật Cấm Khiêu dâm Trẻ em; hình vẽ nằm ngoài phạm vi của luật đó. Theo Điều 175 Bộ luật Hình sự, tội liên quan đến vật phẩm đồi trụy là tội phát tán và tàng trữ để bán, chứ không phải tội tàng trữ riêng tư, vì vậy sở hữu một cuốn manga được bán tại Nhật Bản là hợp pháp ở đây. Quốc gia mà bạn mang trình xem của mình đến có thể nhìn nhận tất cả những điều này theo cách khác.""",
    "GB": """Vương quốc Anh. Bản quyền: không có ngoại lệ sao chép riêng. Ngoại lệ được đưa ra năm 2014 (Điều 28B của Copyright, Designs and Patents Act) đã bị Tòa án Cấp cao hủy bỏ năm 2015, và bản dịch làm cho riêng mình là một bản cải biên không thuộc ngoại lệ nào; sử dụng hợp lý (fair dealing) dành cho nghiên cứu, học tập cá nhân, phê bình và các mục đích tương tự, không dành cho việc đọc giải trí. Vì vậy, bản dịch làm cho riêng mình về mặt pháp luật là xâm phạm (bản thân ảnh chụp là một bản sao nhất thời thuộc loại nằm trong phạm vi của ngoại lệ về bản sao tạm thời), nhưng là vấn đề dân sự: không có tội phạm hình sự nếu không có giao dịch thương mại hoặc phân phối, và chưa từng có trường hợp sử dụng riêng tư, không chia sẻ nào bị truy cứu. Nội dung: tàng trữ "hình ảnh bị cấm về trẻ em" là tội phạm hình sự theo Điều 62 của Coroners and Justice Act 2009, điều luật được soạn ra để bao trùm cả hình vẽ và hình ảnh hoạt hình, với mức phạt tù đến ba năm. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "US": """Hoa Kỳ. Bản quyền: không có ngoại lệ cho việc sử dụng riêng; một bản dịch cá nhân, phi thương mại mà chỉ bạn xem sẽ được xem xét theo nguyên tắc sử dụng hợp lý (fair use), điều mà chưa tòa án nào phán quyết cho tình huống này. Việc chụp một màn hình mà trình xem của bạn đã hiển thị hợp pháp có "vượt qua" biện pháp bảo vệ theo Điều 1201 của DMCA hay không đang được tranh luận theo cả hai chiều và chưa ngã ngũ; TASlation chỉ đọc màn hình. Xâm phạm là vấn đề dân sự, trừ khi là cố ý và nhằm thu lợi hoặc ở quy mô lớn. Nội dung: 18 U.S.C. § 1466A quy định việc tàng trữ hình vẽ, tranh biếm họa hoặc bức họa đồi trụy về trẻ vị thành niên trong hành vi tình dục là tội phạm liên bang; một nhà sưu tập manga Nhật Bản đã nhận tội theo điều luật này vào năm 2009 và sách của ông bị tịch thu. Luật về đồi trụy của các bang cũng được áp dụng.""",
    "CA": """Canada. Bản quyền: Điều 29.22 Luật Bản quyền cho phép bạn sao chép, cho mục đích riêng tư, một tác phẩm mà bạn sở hữu một bản hợp pháp, miễn là không vượt qua khóa kỹ thuật số nào và bản sao không được đem cho người khác; điều này chỉ áp dụng cho việc sao chép, nên bản dịch làm cho riêng mình không thuộc phạm vi đó và về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự và không có thiệt hại nào để đòi khi không chia sẻ gì. Nội dung: Điều 163.1 Bộ luật Hình sự định nghĩa nội dung khiêu dâm trẻ em là bất kỳ hình thức thể hiện bằng hình ảnh nào, và Tòa án Tối cao đã phán quyết trong vụ R. v. Sharpe rằng "người" bao gồm cả người tưởng tượng, nên tài liệu dạng vẽ cũng thuộc phạm vi này; tàng trữ phải chịu mức án tù tối thiểu. Nhân viên biên phòng kiểm tra thiết bị và đã từng buộc tội một du khách vì manga trong một máy tính xách tay. Đừng mang theo bất cứ thứ gì bạn không chắc chắn.""",
    "AU": """Úc. Bản quyền: Điều 43C Luật Bản quyền cho phép bạn sao chép một cuốn sách bạn sở hữu sang định dạng khác, một lần, để sử dụng riêng; không có ngoại lệ chung cho việc sử dụng riêng, và bản dịch làm cho riêng mình là một bản cải biên không thuộc ngoại lệ nào, nên về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự. Nội dung: Bộ luật Hình sự liên bang và luật của các bang về tài liệu xâm hại trẻ em bao trùm cả tài liệu dạng vẽ và hoạt hình, vì phán quyết McEwen v Simmons (NSW, 2008) cho rằng một nhân vật hoạt hình có thể là một "người"; tàng trữ là tội nghiêm trọng. Các ấn phẩm bị từ chối phân loại không được bán hoặc nhập khẩu, ở một số bang việc tàng trữ chúng là phạm tội, và nhân viên biên phòng có thể kiểm tra các thiết bị bạn mang theo khi đi lại. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "NZ": """New Zealand. Bản quyền: không có ngoại lệ chung cho việc sử dụng riêng; ngoại lệ chuyển đổi định dạng chỉ áp dụng cho bản ghi âm, và bản dịch làm cho riêng mình không được bao gồm, nên về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự. Nội dung: theo Luật Phân loại Phim, Video và Ấn phẩm, một ấn phẩm, kể cả hình vẽ và manga, có thể bị coi là "phản cảm" (objectionable), và biết rõ mà vẫn tàng trữ một ấn phẩm phản cảm là tội phạm với mức phạt tù đến mười năm; đã có những vụ truy tố liên quan đến manga hentai. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "IE": """Ireland. Bản quyền: không có ngoại lệ sao chép riêng; quy định gần nhất là sử dụng hợp lý (fair dealing) cho nghiên cứu hoặc học tập cá nhân, và quy định này không dành cho việc đọc giải trí, nên bản dịch làm cho riêng mình về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự. Nội dung: Luật Buôn bán Trẻ em và Khiêu dâm năm 1998 định nghĩa nội dung khiêu dâm trẻ em là bất kỳ hình thức thể hiện bằng hình ảnh nào về một người là trẻ em hoặc trông như trẻ em, trong đó các nhân vật dạng vẽ được nêu rõ là thuộc phạm vi này khi ấn tượng chủ đạo là một đứa trẻ; biết rõ mà vẫn tàng trữ là tội phạm với mức phạt tù đến năm năm. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "DE": """Đức. Bản quyền: § 53 UrhG cho phép cá nhân tạo bản sao để sử dụng riêng từ một nguồn không rõ ràng là bất hợp pháp, và § 23 cho phép tự do tạo ra một bản cải biên như bản dịch; chỉ việc công bố hoặc khai thác nó mới cần sự đồng ý của tác giả. Vì vậy, việc đọc bằng TASlation cho riêng mình có cơ sở vững chắc, miễn là không vượt qua biện pháp bảo vệ kỹ thuật nào (§ 95a), điều mà TASlation không làm. Nội dung: § 184b StGB hình sự hóa việc tàng trữ các mô tả hành vi xâm hại tình dục trẻ em tái hiện một sự kiện có thật hoặc gần với thực tế ("wirklichkeitsnahes"); các hình vẽ rõ ràng là hư cấu nhìn chung nằm ngoài phạm vi này, những hình vẽ gần với thực tế thì không, và §§ 184c và 184 điều chỉnh thanh thiếu niên và các nội dung khiêu dâm khác.""",
    "AT": """Áo. Bản quyền: § 42 UrhG cho phép cá nhân sao chép một tác phẩm để sử dụng riêng; việc tự dịch cho riêng mình không được bao hàm rõ ràng, nhưng pháp luật Áo, giống như pháp luật Đức, đòi hỏi sự đồng ý của tác giả đối với việc khai thác một bản cải biên chứ không phải đối với việc tạo ra nó. Nội dung: § 207a StGB hình sự hóa việc tàng trữ các mô tả tình dục về trẻ vị thành niên, và vì câu chữ của điều này bao trùm cả các mô tả "gần với thực tế" ("wirklichkeitsnahe"), các hình vẽ gần với thực tế thuộc phạm vi điều chỉnh, còn những hình vẽ rõ ràng là hư cấu nhìn chung thì không.""",
    "CH": """Thụy Sĩ. Bản quyền: Điều 19 Luật Bản quyền cho phép mọi hình thức sử dụng một tác phẩm đã công bố trong phạm vi riêng tư, bao gồm cả việc dịch nó cho riêng mình, miễn là không vượt qua biện pháp bảo vệ kỹ thuật nào. Nội dung: Điều 197 Bộ luật Hình sự coi các mô tả hành vi tình dục với trẻ vị thành niên chưa từng xảy ra, kể cả dạng vẽ và hoạt hình, là nội dung khiêu dâm nặng, và việc tàng trữ chúng để tự sử dụng bị trừng phạt, trừ khi tác phẩm có giá trị văn hóa hoặc khoa học đáng được bảo vệ. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "FR": """Pháp. Bản quyền: Điều L122-5 Bộ luật Sở hữu trí tuệ cho phép sao chép riêng từ một nguồn hợp pháp, nhưng Điều L122-4 khiến mọi bản dịch không có sự đồng ý của tác giả đều bất hợp pháp, kể cả bản dịch không ai thấy; đó là vấn đề dân sự và không có thiệt hại nào để đòi chừng nào không chia sẻ gì. Nội dung: Điều 227-23 Bộ luật Hình sự hình sự hóa việc tàng trữ hình ảnh hoặc "sự thể hiện" khiêu dâm về trẻ vị thành niên, và chính phủ đã tuyên bố rằng một hình vẽ là một sự thể hiện; từ năm 2013, điều này cũng áp dụng cho hình ảnh của những người có ngoại hình của trẻ vị thành niên. Các vụ truy tố liên quan đến manga rất hiếm, nhưng văn bản luật cho phép điều đó.""",
    "BE": """Bỉ. Bản quyền: Bộ luật Kinh tế cho phép sao chép riêng trong phạm vi gia đình (Điều XI.190); việc điều đó có bao gồm bản dịch làm cho riêng mình hay không chưa được xác định, vì vậy hãy coi bản dịch như vậy là được dung thứ chứ không phải được cho phép, và đừng bao giờ chia sẻ nó. Nội dung: Bộ luật Hình sự (Điều 417/13, trước đây là 383bis) hình sự hóa việc biết rõ mà vẫn tàng trữ tài liệu thể hiện bằng hình ảnh một trẻ vị thành niên, hoặc một người trông như trẻ vị thành niên, trong hành vi tình dục, thật hoặc mô phỏng; cảnh sát đã tuyên bố rằng manga có thể thuộc phạm vi này dù không có trẻ vị thành niên thật nào liên quan. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "NL": """Hà Lan. Bản quyền: Điều 16b Luật Bản quyền cho phép tạo một bản sao từ một nguồn hợp pháp để bạn tự luyện tập, học tập hoặc sử dụng, và vì luật này coi bản dịch là một hình thức sao chép (Điều 13), bản dịch làm cho riêng mình cũng được bao gồm. Nội dung: Bộ luật Hình sự (Điều 240b, đã chuyển sang Điều 252) hình sự hóa việc tàng trữ nội dung khiêu dâm trẻ em ảo khi nó giống thật; hình vẽ và hoạt hình nằm ngoài phạm vi này trừ khi chúng khó có thể phân biệt với hình ảnh của một đứa trẻ thật, và các tòa án chưa vạch ranh giới đó một cách nhất quán. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "ES": """Tây Ban Nha. Bản quyền: Điều 31.2 Luật Sở hữu trí tuệ cho phép sao chép riêng từ một nguồn hợp pháp (được chi trả bằng khoản phí bù đắp), nhưng việc chuyển thể, bao gồm cả dịch thuật (Điều 21), không có ngoại lệ cho sử dụng riêng, nên bản dịch làm cho riêng mình về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự. Nội dung: Điều 189 Bộ luật Hình sự hình sự hóa việc tàng trữ nội dung khiêu dâm trẻ em, được định nghĩa là bao gồm cả "hình ảnh giống thật" của trẻ vị thành niên; Thông tư 2/2015 của Viện Công tố nêu rằng phim hoạt hình và manga không phải là hình ảnh giống thật và nằm ngoài phạm vi này, trong khi các hình vẽ giống thật và hình ảnh của những người trông như trẻ vị thành niên vẫn thuộc phạm vi điều chỉnh.""",
    "MX": """Mexico. Bản quyền: điểm IV Điều 148 Luật Bản quyền Liên bang cho phép tạo một bản sao duy nhất của một tác phẩm để người tạo bản sao sử dụng cho cá nhân và riêng tư, không vì lợi nhuận; dịch thuật không được bao gồm, nên bản dịch làm cho riêng mình về mặt pháp luật là xâm phạm, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Điều 202 Bộ luật Hình sự Liên bang hình sự hóa việc tàng trữ nội dung khiêu dâm trẻ em; điều này được soạn xoay quanh những người thật dưới mười tám tuổi, và tài liệu dạng vẽ không rõ ràng là thuộc phạm vi điều chỉnh.""",
    "AR": """Argentina. Bản quyền: Luật 11.723 không có ngoại lệ sao chép riêng, nên ngay cả một bản dịch cho riêng mình về mặt pháp luật cũng là xâm phạm; chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Điều 128 Bộ luật Hình sự, được sửa đổi năm 2018, trừng phạt việc chỉ đơn thuần tàng trữ các "sự thể hiện" tình dục của người dưới mười tám tuổi; việc một hình vẽ có phải là sự thể hiện như vậy hay không đang gây tranh cãi giữa các luật gia và chưa có tòa án nào giải quyết, vì vậy hãy coi tài liệu dạng vẽ là một rủi ro.""",
    "BR": """Brazil. Bản quyền: Luật 9.610 chỉ cho phép sao chép những đoạn trích nhỏ để người sao chép sử dụng riêng (điểm II Điều 46); một bản dịch làm cho riêng mình về mặt pháp luật là xâm phạm, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Đạo luật về Trẻ em và Thanh thiếu niên (Điều 241-B và 241-C) hình sự hóa việc tàng trữ các cảnh tình dục có trẻ em hoặc thanh thiếu niên, kể cả những cảnh được mô phỏng bằng cách chỉnh sửa hoặc ghép "bất kỳ hình thức thể hiện bằng hình ảnh nào khác", mà các luật gia hiểu là bao gồm cả hình vẽ; các tòa án chưa giải quyết dứt điểm vấn đề này đối với manga.""",
    "PT": """Bồ Đào Nha. Bản quyền: điểm a khoản 2 Điều 75 Bộ luật Quyền tác giả cho phép sao chép để sử dụng riêng (được chi trả bằng khoản phí bù đắp); dịch thuật là một quyền riêng biệt không có ngoại lệ cho sử dụng riêng, nên bản dịch làm cho riêng mình về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự. Nội dung: Điều 176 Bộ luật Hình sự hình sự hóa việc tàng trữ tài liệu khiêu dâm có "sự thể hiện giống thật" của trẻ vị thành niên; các hình vẽ cách điệu nhìn chung nằm ngoài phạm vi này, những hình vẽ giống thật thì không, và ranh giới này đang được tranh luận.""",
    "IT": """Ý. Bản quyền: ngoại lệ sao chép riêng (Điều 71-sexies Luật 633/1941) chỉ áp dụng cho bản ghi âm và ghi hình, và dịch thuật là một quyền độc quyền không có ngoại lệ cho sử dụng riêng, nên bản dịch làm cho riêng mình về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự. Nội dung: Điều 600-quater.1 Bộ luật Hình sự mở rộng tội tàng trữ sang các hình ảnh "ảo" khiến những tình huống không có thật trông như thật; trong một thời gian dài, hình vẽ được hiểu là nằm ngoài phạm vi này, nhưng năm 2025 Tòa Phá án đã mở rộng khái niệm này sang các hình ảnh được tạo ra bằng xử lý đồ họa không liên quan đến tình huống có thật, và một nhà sưu tập truyện tranh đã bị truy tố. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "PL": """Ba Lan. Bản quyền: Điều 23 Luật Bản quyền cho phép sử dụng cá nhân một tác phẩm đã công bố, và phạm vi cho phép này rộng; một bản dịch giữ cho riêng mình nhìn chung được hiểu là thuộc phạm vi đó, còn việc chia sẻ nó thì không. Nội dung: Điều 202 § 4b Bộ luật Hình sự hình sự hóa việc tàng trữ nội dung khiêu dâm có "hình ảnh được tạo ra hoặc chỉnh sửa" của trẻ vị thành niên; việc một hình vẽ có phải là hình ảnh như vậy hay không đang được tranh luận, và những hình vẽ giống thật có nhiều khả năng bị coi là như vậy hơn.""",
    "RU": """Nga. Bản quyền: Điều 1273 Bộ luật Dân sự cho phép sao chép cho mục đích cá nhân; dịch thuật là một quyền riêng biệt không có ngoại lệ cho sử dụng cá nhân, nên bản dịch làm cho riêng mình không được cho phép rõ ràng, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Điều 242.1 Bộ luật Hình sự chỉ trừng phạt việc làm ra, tàng trữ và vận chuyển các hình ảnh khiêu dâm về trẻ vị thành niên khi nhằm mục đích phát tán, nên chỉ riêng việc tàng trữ riêng tư không cấu thành tội này, và việc các hình ảnh dạng vẽ hay hoạt hình có được tính hay không chưa được xác định; Điều 242 điều chỉnh các nội dung khiêu dâm khác khi bị phát tán.""",
    "TR": """Thổ Nhĩ Kỳ. Bản quyền: Điều 38 Luật về Tác phẩm Trí tuệ và Nghệ thuật cho phép sao chép một tác phẩm để sử dụng cá nhân không nhằm mục đích thương mại; dịch thuật là một quyền riêng biệt không có ngoại lệ cho sử dụng cá nhân, nên bản dịch làm cho riêng mình không được cho phép rõ ràng, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: khoản 3 Điều 226 Bộ luật Hình sự trừng phạt việc tàng trữ hoặc lưu trữ hình ảnh đồi trụy có sử dụng trẻ em, hoặc những người trông giống trẻ em, và những người hành nghề luật hiểu điều này là bao trùm cả các mô tả dạng vẽ và hoạt hình; tàng trữ bị phạt tù từ hai đến năm năm. Tàng trữ riêng tư tài liệu đồi trụy chỉ có người lớn không phải là phạm tội.""",
    "ID": """Indonesia. Bản quyền: Điều 46 Luật Bản quyền cho phép tạo một bản sao của một tác phẩm đã công bố để sử dụng cá nhân; dịch thuật không được bao gồm, nên bản dịch làm cho riêng mình không được cho phép rõ ràng, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Luật Khiêu dâm (44/2008) định nghĩa nội dung khiêu dâm là bao gồm cả tranh biếm họa và hoạt hình và cấm tàng trữ chúng, nhưng phần giải thích của luật này loại trừ việc tàng trữ cho bản thân và vì lợi ích của chính mình; việc phát tán, kể cả trên mạng theo Luật ITE, là tội phạm. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn, và đừng chia sẻ bất cứ thứ gì.""",
    "VN": """Việt Nam. Bản quyền: Điều 25 Luật Sở hữu trí tuệ cho phép tự sao chép một bản để nghiên cứu khoa học hoặc học tập của cá nhân, không phải để đọc giải trí, và không bao gồm việc dịch; bản dịch làm cho riêng mình không được cho phép rõ ràng, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Điều 326 Bộ luật Hình sự trừng phạt việc làm ra, sao chép, vận chuyển hoặc tàng trữ văn hóa phẩm đồi trụy nhằm phổ biến, với mức án tùy theo số lượng; chỉ tàng trữ cho riêng mình không phải là tội này, nhưng có thể bị xử phạt hành chính, và thế nào là đồi trụy do cơ quan chức năng quyết định. Đừng chia sẻ bất cứ thứ gì.""",
    "CN": """Trung Quốc. Bản quyền: khoản 1 Điều 24 Luật Bản quyền cho phép sử dụng một tác phẩm đã công bố cho mục đích học tập, nghiên cứu hoặc thưởng thức cá nhân, điều này được hiểu là bao gồm cả việc tự dịch cho riêng mình. Nội dung: Bộ luật Hình sự (Điều 363 đến 367) trừng phạt việc sản xuất, buôn bán hoặc phát tán vật phẩm đồi trụy, kể cả truyện tranh, và Luật Xử phạt Quản lý Trị an trừng phạt việc phát tán; chỉ đơn thuần tàng trữ riêng tư không phải là vi phạm pháp luật, nhưng bất cứ thứ gì bạn chia sẻ hay đăng tải đều là vi phạm.""",
    "TW": """Đài Loan. Bản quyền: Điều 51 Luật Bản quyền cho phép sao chép để sử dụng cho cá nhân hoặc gia đình không vì lợi nhuận, và Điều 63 cho phép dịch một tác phẩm cho mục đích sử dụng đó. Nội dung: Luật Phòng chống Bóc lột Tình dục Trẻ em và Thiếu niên hình sự hóa việc tàng trữ hình ảnh tình dục của trẻ em và thiếu niên, kể cả những hình ảnh do máy tính tạo ra trông như thật; việc tài liệu thuần túy dạng vẽ hoặc hoạt hình có thuộc phạm vi điều chỉnh hay không đang được tranh luận và chưa được tòa án giải quyết.""",
    "HK": """Hồng Kông. Bản quyền: không có ngoại lệ sao chép riêng; quy định gần nhất là sử dụng hợp lý (fair dealing) cho nghiên cứu hoặc học tập cá nhân, và bản dịch làm cho riêng mình là một bản cải biên không thuộc ngoại lệ nào, nên về mặt pháp luật là xâm phạm, nhưng là vấn đề dân sự. Nội dung: Pháp lệnh Phòng chống Văn hóa phẩm Khiêu dâm Trẻ em (Cap. 579) hình sự hóa việc tàng trữ hình ảnh mô tả theo cách tình dục một người dưới mười sáu tuổi, hoặc được mô tả là dưới mười sáu tuổi, kể cả hình vẽ, với căn cứ bào chữa là giá trị nghệ thuật; Pháp lệnh Kiểm soát Vật phẩm Đồi trụy và Khiếm nhã điều chỉnh các tài liệu khác.""",
    "SG": """Singapore. Bản quyền: Luật Bản quyền 2021 không có ngoại lệ sao chép riêng đối với sách; bản dịch làm cho riêng mình sẽ được xem xét theo quy định về sử dụng hợp lý (fair use) của luật này, quy định mà chưa tòa án nào áp dụng cho tình huống này, vì vậy về mặt pháp luật nó có thể là xâm phạm, nhưng là vấn đề dân sự. Nội dung: Bộ luật Hình sự (Điều 377BK) quy định việc tàng trữ tài liệu xâm hại trẻ em là tội phạm có thể bị phạt tù đến năm năm, và tài liệu này bao gồm cả hình vẽ mô tả một người mà theo một người quan sát hợp lý thì trông như dưới mười sáu tuổi; Luật Ấn phẩm Không mong muốn và Luật Điện ảnh quy định ấn phẩm và phim đồi trụy là phạm tội ngay cả khi tàng trữ riêng tư. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "PH": """Philippines. Bản quyền: Điều 187 Bộ luật Sở hữu trí tuệ cho phép một bản sao riêng duy nhất cho nghiên cứu và học tập cá nhân, không phải để đọc giải trí, và dịch thuật không được bao gồm; bản dịch làm cho riêng mình không được cho phép rõ ràng, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Luật Cộng hòa 11930 (2022, thay thế Luật Chống Khiêu dâm Trẻ em) định nghĩa "trẻ em" bao gồm cả những hình ảnh do máy tính tạo ra, được chế tác bằng kỹ thuật số hoặc thủ công để trông như một đứa trẻ, và quy định việc tàng trữ là phạm tội; tàng trữ từ ba tài liệu trở lên bị suy đoán là nhằm mục đích phát tán. Đừng giữ lại bất cứ thứ gì bạn không chắc chắn.""",
    "KR": """Hàn Quốc. Bản quyền: Điều 30 Luật Bản quyền cho phép sao chép để sử dụng riêng, và Điều 36 cho phép dịch một tác phẩm cho mục đích sử dụng đó. Nội dung: Luật Bảo vệ Trẻ em và Thanh thiếu niên khỏi Tội phạm Tình dục coi các mô tả tình dục về người hoặc hình tượng có thể được nhận biết rõ ràng là trẻ em hoặc thanh thiếu niên, kể cả hoạt hình và manga, là tài liệu bóc lột tình dục trẻ em hoặc thanh thiếu niên, và việc mua, tàng trữ hoặc xem chúng là tội phạm; một lần sửa đổi năm 2025 đã bỏ yêu cầu phải chứng minh rằng bạn đã biết.""",
}
